fn walk(whole: { ...u, ...v }, left: { ...s }, n: Int): Int
  where u disjoint s = {
  let next = if n == 0 then 0 else walk(whole, left, n + -1);
  let shown = show(1 + 2);
  if shown == "3" then 1 else 2
};

fn later(n: Int): Int = n + 1;

fn bad(): Int = {
  let x = later(1, 2);
  x + 1
};

fn main(): Int = 0;
